-- Table: tyre_kit_disk_size
-- Rows exported: 93544

DROP TABLE IF EXISTS `tyre_kit_disk_size`;
CREATE TABLE `tyre_kit_disk_size` (
  `id` int unsigned NOT NULL,
  `kit_id` int unsigned NOT NULL,
  `width` decimal(4,2) NOT NULL,
  `diameter` decimal(4,1) NOT NULL,
  `et` smallint NOT NULL,
  `pcd` decimal(6,2) DEFAULT NULL,
  `bolt_count` tinyint unsigned DEFAULT NULL,
  `dia` decimal(6,2) DEFAULT NULL,
  `is_stock` tinyint(1) NOT NULL DEFAULT '0',
  `axle` tinyint unsigned NOT NULL DEFAULT '0',
  `axle_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `str_size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_kit` (`kit_id`),
  KEY `idx_size` (`width`,`diameter`,`et`),
  KEY `idx_diameter` (`diameter`),
  KEY `idx_pcd_bolt` (`bolt_count`,`pcd`),
  KEY `idx_dia` (`dia`),
  KEY `idx_kit_sort` (`kit_id`,`is_stock`,`diameter`,`width`,`et`,`axle`),
  KEY `idx_bolt_pcd_diam_stock` (`bolt_count`,`pcd`,`diameter`,`is_stock`),
  KEY `idx_diam_width_et` (`diameter`,`width`,`et`,`is_stock`),
  CONSTRAINT `fk_tyre_disksize_kit` FOREIGN KEY (`kit_id`) REFERENCES `tyre_car_kit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

